script:
(function () {
  'use strict';
  // Retirement contribution effects on your paycheck (tax year 2026): take-home with and without a
  // pre-tax deferral to a 401(k), 403(b), 457(b) or SIMPLE plan. The deferral is exempt from federal
  // income tax and the flat state rate, but Social Security and Medicare still apply, so
  //   take-home drop = deferral - federal tax saved - state tax saved.
  // Each plan's 2026 limit for your age caps the deferral. A 401(k)/403(b) and a 457(b) have separate
  // limits, so the "both" row adds them. Age catch-ups: 401(k), 403(b), governmental 457(b) and SIMPLE
  // plans; not 457(b) plans of tax-exempt employers.
  // Checked in Node (fake DOM, whole script): single $75,000 biweekly, 5% 401(k), $100/check, 0% state gives
  // federal $6,273.00, SS $4,488.80, Medicare $1,049.80 a year (same as take-home-paycheck-calculator).
  // $65,000, 8%, 4% state: $200/check deferral cuts take-home by $168 (12% + 4% saved). Limits: 401(k)/403(b)/
  // governmental 457(b) $24,500 / $32,500 / $35,750; tax-exempt 457(b) $24,500 at any age; SIMPLE $17,000 /
  // $21,000 / $22,250; 401(k) + 457(b) at 60-63 = $71,500.
  // ---- 2026 FEDERAL PAYROLL CONSTANTS (tax year 2026) ----------------------------------
  // Copied from take-home-paycheck-calculator (verified there). Brackets and standard
  // deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21). Child tax credit $2,200 and
  // $500 other-dependent credit: IRC 24(h) as amended by P.L. 119-21. Social Security wage base
  // and rate: SSA 2026 fact sheet. Medicare and 0.9% Additional Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200, OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  // ---------------------------------------------------------------------------------------

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) { tax += (Math.min(taxable, upper) - lower) * RATES[i]; marginal = RATES[i]; }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Annual paycheck model. o: gross, status, pretaxDefer (traditional plan deferral: exempt from
  // federal and flat state tax, still FICA wages), rothDefer (after-tax plan deferral), sec125
  // (health premiums etc.: exempt from federal, state and FICA), post (other after-tax deductions),
  // stateRate (%), kids, otherDeps, extraWH (extra federal withholding). All $ amounts are annual.
  function payroll(o) {
    var gross = o.gross, defer = o.pretaxDefer || 0, roth = o.rothDefer || 0;
    var sec125 = Math.min(o.sec125 || 0, Math.max(0, gross - defer));
    var ficaWages = Math.max(0, gross - sec125);
    var fedWages = Math.max(0, gross - defer - sec125);
    var taxable = Math.max(0, fedWages - STANDARD_DEDUCTION[o.status]);
    var bt = bracketTax(taxable, BRACKETS[o.status]);
    var credits = (o.kids || 0) * CHILD_CREDIT + (o.otherDeps || 0) * OTHER_DEPENDENT_CREDIT;
    credits = Math.max(0, credits - Math.ceil(Math.max(0, fedWages - CREDIT_PHASEOUT_START[o.status]) / 1000) * 50);
    var federal = Math.max(0, bt.tax - credits) + (o.extraWH || 0);
    var ss = SS_RATE * Math.min(ficaWages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * ficaWages + ADDL_MEDICARE_RATE * Math.max(0, ficaWages - ADDL_MEDICARE_WITHHOLD_START);
    var state = (o.stateRate || 0) / 100 * fedWages;
    var post = o.post || 0;
    var net = gross - defer - roth - sec125 - federal - ss - medicare - state - post;
    return { gross: gross, defer: defer, roth: roth, sec125: sec125, ficaWages: ficaWages, fedWages: fedWages,
             taxable: taxable, federal: federal, marginal: bt.marginal, ss: ss, medicare: medicare, state: state,
             post: post, net: net, taxes: federal + ss + medicare + state };
  }
  // ---- 2026 PLAN LIMITS (IRS Notice 2025-67, tax year 2026) ------------------------------------
  // 401(k), 403(b), 457(b): $24,500 (402(g) / 457(e)(15)); catch-up $8,000 at 50+, $11,250 at 60-63.
  // SIMPLE IRA / SIMPLE 401(k): $17,000 (408(p)(2)(E)); catch-up $4,000 at 50+, $5,250 at 60-63.
  // (Some smaller-employer SIMPLE plans allow $18,100 with a $3,850 age 50+ catch-up; not modelled.)
  var PLANS = {
    k401:    { name: '401(k)',                        base: 24500, c50: 8000, c60: 11250 },
    b403:    { name: '403(b)',                        base: 24500, c50: 8000, c60: 11250 },
    gov457:  { name: '457(b), governmental',          base: 24500, c50: 8000, c60: 11250 },
    ng457:   { name: '457(b), tax-exempt employer',   base: 24500, c50: 0,    c60: 0 },
    simple:  { name: 'SIMPLE IRA or SIMPLE 401(k)',   base: 17000, c50: 4000, c60: 5250 }
  };
  // ---------------------------------------------------------------------------------------
  function limitFor(plan, band) { var q = PLANS[plan]; return q.base + (band === '60' ? q.c60 : band === '50' ? q.c50 : 0); }

  // o: salary, status, stateRate, sec125, post, kids, otherDeps (annual)
  function run(o, defer) {
    return payroll({ gross: o.salary, status: o.status, pretaxDefer: defer, sec125: o.sec125, post: o.post,
                     stateRate: o.stateRate, kids: o.kids, otherDeps: o.otherDeps });
  }
  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var wholeFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function whole(x) { return wholeFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function signed(x) { if (Math.abs(x) < 0.005) return money(0); return (x < 0 ? '−' : '+') + moneyFmt.format(Math.abs(x)); }
  function minus(x) { return Math.abs(x) < 0.005 ? money(0) : '−' + moneyFmt.format(Math.abs(x)); }
  function pctText(x) { return (Math.round(x * 10) / 10) + '%'; }
  function num(id) { var el = document.getElementById(id); if (!el) return NaN; var v = parseFloat(el.value); return isNaN(v) ? NaN : v; }
  function val(id) { var el = document.getElementById(id); return el ? el.value : ''; }
  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  // rows: arrays of cells; a cell is a string or {t: text, strong: bool}. The first cell is a row header.
  // A row given as {group: text, span: n} becomes a full-width group heading.
  function fillTable(id, rows) {
    var body = document.getElementById(id);
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (row) {
      var tr = document.createElement('tr');
      if (row.group) {
        var g = document.createElement('th');
        g.setAttribute('scope', 'colgroup'); g.colSpan = row.span; g.textContent = row.group;
        tr.appendChild(g); body.appendChild(tr); return;
      }
      row.forEach(function (c, i) {
        var el = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) el.setAttribute('scope', 'row');
        var text = typeof c === 'object' ? c.t : c;
        if (typeof c === 'object' && c.strong) { var s = document.createElement('strong'); s.textContent = text; el.appendChild(s); }
        else el.textContent = text;
        tr.appendChild(el);
      });
      body.appendChild(tr);
    });
  }
  function showError(id, msg) { var e = document.getElementById(id); if (!e) return; e.hidden = !msg; e.textContent = msg || ''; }
  function showNote(id, notes) { var n = document.getElementById(id); if (!n) return; n.hidden = notes.length === 0; n.textContent = notes.join(' '); }
  function wire(formId, update) {
    document.addEventListener('DOMContentLoaded', function () {
      var form = document.getElementById(formId);
      if (!form) return;
      var run = function () { try { update(); } catch (err) { /* keep the page usable */ } };
      form.addEventListener('input', run);
      form.addEventListener('change', run);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
      run();
    });
  }
  function update() {
    var o = { salary: num('rcSalary'), status: val('rcStatus'), stateRate: num('rcState'),
              kids: Math.round(num('rcKids')), otherDeps: Math.round(num('rcOtherDeps')) };
    var p = parseInt(val('rcFreq'), 10), plan = val('rcPlan'), band = val('rcAge'), mode = val('rcMode');
    var amt = num('rcAmount'), pre = num('rcPretax'), post = num('rcPost');
    if (!BRACKETS[o.status]) o.status = 'single';
    if (!PLANS[plan]) plan = 'k401';
    if (!(p > 0)) p = 26;
    var all = [o.salary, o.stateRate, o.kids, o.otherDeps, amt, pre, post];
    if (all.some(function (v) { return !isFinite(v) || v < 0; }) || o.salary > 1e8 || o.stateRate > 20 ||
        o.kids > 20 || o.otherDeps > 20 || (mode === 'pct' && amt > 100)) {
      showError('rcError', 'Enter a salary, a contribution from 0 to 100% (or a dollar amount), a state rate from 0 to 20% and non-negative amounts.');
      return;
    }
    o.sec125 = pre * p; o.post = post * p;
    var room = o.salary - o.sec125 - o.post;
    if (room < 0) { showError('rcError', 'Your other deductions add up to more than your pay.'); return; }
    showError('rcError', '');

    var wanted = mode === 'pct' ? o.salary * amt / 100 : amt * p;
    var lim = limitFor(plan, band);
    var defer = Math.min(wanted, lim, room);
    var a = run(o, 0), b = run(o, defer);
    var drop = a.net - b.net, fedSaved = a.federal - b.federal, stSaved = a.state - b.state;
    setText('rcDrop', minus(drop / p));
    setText('rcDefer', money(defer / p));
    setText('rcTaxSaved', money((fedSaved + stSaved) / p));
    setText('rcNetWithout', money(a.net / p));
    setText('rcNetWith', money(b.net / p));
    setText('rcFedSaved', whole(fedSaved));
    setText('rcStateSaved', whole(stSaved));
    setText('rcPerDollar', defer > 0.005 ? money(drop / defer) : '–');
    setText('rcLimit', whole(lim));
    setText('rcMaxPct', o.salary > 0 ? pctText(Math.min(lim, room) / o.salary * 100) : '–');
    setText('rcMaxPer', money(Math.min(lim, room) / p));

    var d = function (x, y) { return signed(-(y - x) / p); };
    fillTable('rcCompare', [
      ['Gross pay', money(a.gross / p), money(b.gross / p), signed(0)],
      [PLANS[plan].name + ' deferral', money(0), minus(defer / p), signed(-defer / p)],
      ['Federal income tax', minus(a.federal / p), minus(b.federal / p), d(a.federal, b.federal)],
      ['Social Security', minus(a.ss / p), minus(b.ss / p), d(a.ss, b.ss)],
      ['Medicare', minus(a.medicare / p), minus(b.medicare / p), d(a.medicare, b.medicare)],
      ['State and local income tax', minus(a.state / p), minus(b.state / p), d(a.state, b.state)],
      ['Other deductions', minus((a.sec125 + a.post) / p), minus((b.sec125 + b.post) / p), signed(0)],
      [{ t: 'Take-home pay', strong: true }, { t: money(a.net / p), strong: true }, { t: money(b.net / p), strong: true }, { t: signed(-drop / p), strong: true }]
    ]);

    var rows = [];
    ['k401', 'gov457', 'ng457', 'simple', 'both'].forEach(function (key) {
      var l = key === 'both' ? limitFor('k401', band) + limitFor('gov457', band) : limitFor(key, band);
      var name = key === 'both' ? '401(k) or 403(b) plus governmental 457(b)' : key === 'k401' ? '401(k) or 403(b)' : PLANS[key].name;
      var dmax = Math.min(l, room), r = run(o, dmax);
      rows.push([dmax < l - 0.005 ? name + ' (limited by pay)' : name, whole(l), money(dmax / p), money(r.net / p), minus((a.net - r.net) / p),
                 dmax > 0 ? money((a.net - r.net) / dmax) : '–']);
    });
    fillTable('rcPlans', rows);

    var notes = [];
    if (wanted > defer + 0.005) notes.push('Your deferral is capped at ' + whole(defer) + (defer < lim ? ', what is left of your pay after other deductions.' : ', the ' + TAX_YEAR + ' ' + PLANS[plan].name + ' limit for your age.'));
    if (plan === 'ng457' && band !== 'u50') notes.push('457(b) plans of tax-exempt employers do not allow age-based catch-up contributions.');
    if (band !== 'u50' && plan !== 'simple' && plan !== 'ng457') notes.push('If your 2025 Social Security wages from this employer were over $150,000, your catch-up contributions must be Roth (after-tax) from 2026, which would make the take-home drop larger.');
    showNote('rcNote', notes);
  }

  wire('rcForm', update);
})();
